b_married = observation(entity='Alice', entity_source='s30', predicate='married', predicate_source='s3')
b_spouse_death = observation(entity='Bob', entity_source='s30', predicate='spouse died', predicate_source='s4')
b_tax_year = observation(entity='Bob', entity_source='s31', predicate='taxable year', predicate_source='s31')
b_two_years_before_death = observation(entity='Bob', entity_source='s30', predicate='two years immediately preceding the taxable year', predicate_source='s4')
b_dependent_child = observation(entity='Bob', entity_source='s30', predicate='dependent (son, stepson, daughter, or stepdaughter)', predicate_source='s5')
b_dependent_condition = observation(entity='Bob', entity_source='s30', predicate='entitled to a deduction for the taxable year', predicate_source='s5')
b_household_principal_place = observation(entity='Bob', entity_source='s30', predicate='maintains as his home a household which constitutes for the taxable year the principal place of abode', predicate_source='s5')
b_household_cost = observation(entity='Bob', entity_source='s30', predicate='over half of the cost of maintaining the household during the taxable year is furnished by such individual', predicate_source='s6')
b_remarriage = observation(entity='Bob', entity_source='s30', predicate='remarried at any time before the close of the taxable year', predicate_source='s9')
b_joint_return = observation(entity='Bob', entity_source='s30', predicate='a joint return could have been made', predicate_source='s10')
b_nonresident_alien = observation(entity='Alice', entity_source='s30', predicate='nonresident alien', predicate_source='s10')
b_spouse_death_tax_year = observation(entity='Bob', entity_source='s30', predicate='spouse died during the taxable year', predicate_source='s25')
@scope('s0')
def definitions_scope():
    return True
@scope('s1')
def surviving_spouse_scope():
    return definitions_scope
@scope('s2')
def general_surviving_spouse_scope():
    return surviving_spouse_scope
@scope('s3')
def general_surviving_spouse_definition_scope():
    return general_surviving_spouse_scope
@scope('s4')
def surviving_spouse_death_scope():
    return general_surviving_spouse_definition_scope and b_spouse_death and b_tax_year
@scope('s5')
def dependent_child_scope():
    return general_surviving_spouse_definition_scope and b_dependent_child and b_dependent_condition
@scope('s6')
def household_principal_place_scope():
    return general_surviving_spouse_definition_scope and b_household_principal_place and b_household_cost
@rule('s4', otherwise=False)
def surviving_spouse_death_test():
    return (surviving_spouse_scope and b_two_years_before_death and b_dependent_child and b_dependent_condition and b_household_principal_place and b_household_cost)
@rule('s9', otherwise=False)
def remarriage_test():
    return (surviving_spouse_scope and b_remarriage)
@rule('s10', otherwise=False)
def joint_return_test():
    return (surviving_spouse_scope and b_joint_return)
@rule('s25', otherwise=False)
def spouse_death_tax_year_test():
    return (surviving_spouse_scope and b_spouse_death_tax_year)
query = ('Entailment' if surviving_spouse_death_test else 'Contradiction')
